// all in [0, zero] = 0
// all in (zero, i) = 1
// all in (two, len - 1] = 2
func sortColors(nums []int) {
	size := len(nums)
	if size < 2 {
		return
	}
	zero, two, i := -1, size-1, 0
	for i <= two {
		if nums[i] == 0 {
			zero++
			nums[i], nums[zero] = nums[zero], nums[i]
			i++
		} else if nums[i] == 1 {
			i++
		} else {
			nums[i], nums[two] = nums[two], nums[i]
			two--
		}
	}
}
